			text = [=[{link:edwin-vancleef}Edwin VanCleef{/link} había escrito una carta a Baros y la había sellado, pero nunca salió de las {link:the-deadmines}Minas de la Muerte{/link}. Cuando por fin llegó a manos del arquitecto, la leyó con atención. Sus palabras dirigieron sus pensamientos hacia {link:the-stockade}Las Mazmorras{/link}, donde estaba preso uno de los lugartenientes de VanCleef, {link:bazil-thredd}Bazil Thredd{/link}.]=],
		},
		{
			title = "Una carta de Auberdine",
			hint = [=[Lleve la carta del anciano de Auberdine a través del mar hasta Ventormenta.]=],
			text = [=[El anciano {link:thundris-windweaver}Thundris Windweaver{/link} de {link:auberdine}Auberdine{/link} escribió a Baros para pedir que no se olvidara su pequeña ciudad. Baros se rio cuando llegó el portador de la carta, y su sonrisa se desvaneció mientras leía. Su respuesta fue honesta. Las arcas de {link:stormwind-city}Ventormenta{/link} no son lo que eran, y lo que queda está muy repartido. No tenía nada que enviar salvo sus disculpas.]=],
		},
	},
	mentions = {
