Translate("esES", "grayson-shadowbreaker", {
	title = "Grayson Shadowbreaker",
	subtitle = "Señor de los paladines de la Catedral",
	found = "La Catedral de la Luz, Plaza de la Catedral",
	hint = [=[Busque al señor que instruye a los paladines en la Catedral de la Luz.]=],
	allegiance = "Iglesia de la Luz Sagrada · Paladines de Ventormenta",
	aliases = { "Lord Grayson Shadowbreaker", "Shadowbreaker" },
	sections = {
		{
			title = "Resumen",
			text = [=[Lord Grayson Shadowbreaker instruye a los paladines de {link:stormwind-city}Ventormenta{/link} en las salas de la {link:cathedral-of-light}Catedral de la Luz{/link}. Es caballero y maestro, y sus alumnos aprenden de él que la {link:holy-light}Luz Sagrada{/link} pide sacrificio antes de conceder fuerza. Los jóvenes paladines del reino pasan por sus manos, y también los veteranos cuando buscan un camino más duro.]=],
		},
		{
			title = "Importancia",
			text = [=[{link:captain-grayson}Grayson{/link} mantiene viva la unión de fe y acero que la Iglesia de la {link:holy-light}Luz Sagrada{/link} forjó tras la {link:first-war}Primera Guerra{/link}. Su consejo llega más allá de {link:stormwind-city}Ventormenta{/link}. Envía a los jóvenes paladines enanos a sus propios maestros en {link:ironforge}Forjaz{/link}, y se le confían objetos sagrados que el reino desea mantener a salvo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Instruye a los paladines de la Catedral.
• Envía a los paladines enanos ante Tiza Battleforge, en {link:ironforge}Forjaz{/link}.
• Pone a los paladines probados del reino en un largo camino de pruebas y sacrificio.
• Recibe la Estatuilla de Menethil para custodiarla en la Catedral.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de {link:captain-grayson}Grayson{/link} antes de la Catedral, ni de las hazañas que le valieron su título.]=],
		},
	},
	chapters = {
		{
			title = "Una reliquia de Terenas",
			hint = [=[Lleve a la Catedral una pequeña estatua del viejo rey de Lordaeron.]=],
			text = [=[El rey {link:terenas-menethil}Terenas Menethil{/link} era un hombre humilde al que no le gustaban los monumentos, y pocas imágenes suyas sobrevivieron a la caída de su reino. Cuando una pequeña estatua suya salió de {link:wetlands}Los Humedales{/link}, la Luz pareció reposar en ella. Fue llevada a {link:stormwind-city}Ventormenta{/link} y puesta bajo la custodia de lord {link:captain-grayson}Grayson{/link}, para ser guardada en la {link:cathedral-of-light}Catedral de la Luz{/link}.]=],
		},
		{
			title = "El camino del sacrificio",
			hint = [=[Recorra el largo camino que lord Grayson impone a los paladines del reino.]=],
			text = [=[{link:captain-grayson}Grayson{/link} no concede a la ligera los honores de un paladín. La primera prueba que impone es de sacrificio: una costosa ofrenda a la iglesia de {link:ironforge}Forjaz{/link}, a cambio de un incensario sagrado que guarda su sumo sacerdote.]=],
		},
	},
	mentions = {
		{ text = "Tome of Divinity" },
		{ text = "Emphasis on Sacrifice" },
		{ text = "Lord Grayson Shadowbreaker" },
		{ text = "A Friend of the Family" },
	},
	bonds = {
